// The glossary of the Reference pane: Kwery's own definitions of the terms used in its lessons, each in a sentence
// or two, with links to the lesson or view that shows it.
(function (root) {
  'use strict';
  const K = root.K;
  const C = K.Content = K.Content || {};
  const R = C.reference = C.reference || { statements: [], types: [], glossary: [], settings: [], functions: {}, functionGroups: {}, operators: {}, operatorList: [], functionExamples: {} };
  R.glossary.push(
    // ---- 1: introduction ----
    { id: 'dbms', term: 'Database management system', chapter: 1, def: 'A program that looks after a database: it stores the data, answers queries in a language such as SQL, and lets many people read and change the data at once without corrupting it.', related: ['data-independence', 'transaction'], see: [{ lesson: 'intro-parts' }] },
    { id: 'data-independence', term: 'Data independence', chapter: 1, def: 'Being able to change how one layer of a database is organized without breaking the layer above. With **physical** data independence you can add an index or change the file layout and every query still works unchanged.', related: ['levels-of-abstraction', 'schema'], see: [{ lesson: 'intro-abstraction' }] },
    { id: 'levels-of-abstraction', term: 'Levels of abstraction', chapter: 1, def: 'Three ways of looking at one database: the physical level (bytes, pages and files), the logical level (the tables, columns and constraints) and the view level (the slice a particular application or user works with).', related: ['data-independence', 'view'], see: [{ lesson: 'intro-abstraction' }] },
    { id: 'ddl', term: 'Data-definition language (DDL)', chapter: 1, def: 'The statements that describe the shape of a database rather than its contents: `CREATE`, `ALTER` and `DROP` for tables, views, indexes, types and constraints. The system records their effect in its catalog.', related: ['dml', 'data-dictionary'], see: [{ lesson: 'sql-ddl' }] },
    { id: 'dml', term: 'Data-manipulation language (DML)', chapter: 1, def: 'The statements that read and modify the rows themselves: `SELECT`, `INSERT`, `UPDATE`, `DELETE` and `MERGE`.', related: ['ddl'], see: [{ lesson: 'sql-modify' }] },
    { id: 'data-dictionary', term: 'Data dictionary (catalog)', chapter: 1, def: 'The database\'s description of itself, kept in system tables: which tables, columns, types, constraints, indexes, roles and statistics exist. In Kwery, `\\d` and the `pg_` views read it.', related: ['ddl', 'statistics'] },
    { id: 'dba', term: 'Database administrator', chapter: 1, def: 'The person responsible for keeping a database healthy: its schema, storage, security, backups and performance.', see: [{ lesson: 'intro-users' }] },

    // ---- 2: the relational model ----
    { id: 'relation', term: 'Relation', chapter: 2, def: 'A named collection of rows that all have the same columns, with no duplicate rows and no built-in row order. In SQL it is drawn and used as a table.', related: ['tuple', 'attribute', 'relation-schema'], see: [{ lesson: 'rel-relations' }] },
    { id: 'tuple', term: 'Tuple', chapter: 2, def: 'A single row of a relation, giving one value for each of its attributes.', related: ['relation', 'attribute'], see: [{ lesson: 'rel-relations' }] },
    { id: 'attribute', term: 'Attribute', chapter: 2, def: 'One named column of a relation; every value in that column comes from the attribute\'s domain.', related: ['domain', 'relation'], see: [{ lesson: 'rel-relations' }] },
    { id: 'domain', term: 'Domain', chapter: 2, def: 'The set of values an attribute is allowed to hold, for example whole numbers from 1 to 5, or strings of at most 40 characters.', related: ['atomic-domain', 'attribute'], see: [{ lesson: 'rel-relations' }] },
    { id: 'atomic-domain', term: 'Atomic domain', chapter: 2, def: 'A domain whose values the database never looks inside: a value is used whole, not as a list or a structure with parts. First normal form requires every domain to be atomic.', related: ['domain', '1nf'] },
    { id: 'relation-schema', term: 'Relation schema', chapter: 2, def: 'The definition of a relation: its name and its attributes with their domains. It stays fixed while the rows stored under it come and go.', related: ['relation-instance', 'schema'], see: [{ lesson: 'rel-relations' }] },
    { id: 'relation-instance', term: 'Relation instance', chapter: 2, def: 'The particular rows a relation contains at a given moment.', related: ['relation-schema'], see: [{ lesson: 'rel-relations' }] },
    { id: 'schema', term: 'Database schema', chapter: 2, def: 'The overall design of a database: all of its relation schemas together with the constraints between them. In SQL the word also names a namespace that holds tables and other objects.', related: ['relation-schema', 'schema-diagram'], see: [{ view: 'erd', label: 'Schema diagram' }] },
    { id: 'schema-diagram', term: 'Schema diagram', chapter: 2, def: 'A picture of a database design: each relation as a box listing its attributes, the primary key marked, and an arrow from each foreign key to the relation it refers to.', related: ['schema', 'foreign-key'], see: [{ view: 'erd', label: 'Schema diagram' }] },
    { id: 'null', term: 'Null', chapter: 2, def: 'A special marker meaning a value is missing or does not apply. Any ordinary comparison involving null yields *unknown* rather than true or false.', related: ['three-valued-logic'], see: [{ lesson: 'sql-nulls' }], example: 'select person_id, given_name, family_name from person where home_city is null;' },
    { id: 'superkey', term: 'Superkey', chapter: 2, def: 'Any set of attributes that is enough to tell rows apart: no two rows that could legally exist share the same values for all of them.', related: ['candidate-key', 'primary-key'], see: [{ lesson: 'rel-keys' }] },
    { id: 'candidate-key', term: 'Candidate key', chapter: 2, def: 'A superkey with nothing to spare: remove any one of its attributes and it no longer identifies rows. A relation can have more than one.', related: ['superkey', 'primary-key'], see: [{ lesson: 'rel-keys' }] },
    { id: 'primary-key', term: 'Primary key', chapter: 2, def: 'The candidate key chosen as the official identifier of a relation\'s rows. Its attributes must never be null, and SQL enforces that it is unique.', related: ['candidate-key', 'foreign-key'], see: [{ lesson: 'rel-keys' }, { lesson: 'int-constraints' }] },
    { id: 'foreign-key', term: 'Foreign key', chapter: 2, def: 'A set of attributes in one relation whose values must match the key of some row in another (or the same) relation, the one it refers to.', related: ['referential-integrity', 'primary-key'], see: [{ lesson: 'rel-keys' }, { lesson: 'int-fk' }] },
    { id: 'referential-integrity', term: 'Referential integrity', chapter: 2, def: 'The guarantee that every non-null foreign key value points at a row that really exists. A change that would leave a dangling reference is refused, or handled by an action such as `ON DELETE CASCADE`.', related: ['foreign-key'], see: [{ lesson: 'int-fk' }] },
    { id: 'query-language', term: 'Query language', chapter: 2, def: 'A language for asking a database for information. A procedural one spells out the steps to compute the answer; a declarative one, like SQL or the relational calculus, only describes the answer wanted.', related: ['relational-algebra', 'tuple-relational-calculus'] },
    { id: 'relational-algebra', term: 'Relational algebra', chapter: 2, def: 'A small set of operators, each taking one or two relations and producing a new relation: selection, projection, union, difference, Cartesian product and rename, with joins and others built from them. Queries are written by nesting these operators.', related: ['selection', 'projection', 'natural-join'], see: [{ lesson: 'rel-algebra-basic' }, { view: 'algebra', label: 'Relational algebra' }] },
    { id: 'selection', term: 'Selection (σ)', chapter: 2, def: 'The algebra operator that filters a relation, keeping only the rows for which a condition holds. It corresponds to SQL\'s `WHERE`.', related: ['projection', 'relational-algebra'], see: [{ lesson: 'rel-algebra-basic' }, { view: 'algebra', label: 'Relational algebra' }] },
    { id: 'projection', term: 'Projection (Π)', chapter: 2, def: 'The algebra operator that keeps chosen columns of a relation and discards the others; as a set operation it also drops any duplicate rows this creates. In SQL it is the select list, which keeps duplicates unless you write `DISTINCT`.', related: ['selection'], see: [{ lesson: 'rel-algebra-basic' }, { view: 'algebra', label: 'Relational algebra' }] },
    { id: 'cartesian-product', term: 'Cartesian product (×)', chapter: 2, def: 'Combining two relations by pairing every row of the first with every row of the second. The result has as many rows as the two inputs\' row counts multiplied.', related: ['theta-join', 'natural-join'], see: [{ lesson: 'rel-algebra-join' }] },
    { id: 'theta-join', term: 'Theta join', chapter: 2, def: 'A join that keeps those pairs from the Cartesian product of two relations that satisfy some condition θ. When θ uses only equality comparisons it is called an equi-join.', related: ['cartesian-product', 'natural-join'], see: [{ lesson: 'rel-algebra-join' }, { lesson: 'int-joins' }] },
    { id: 'natural-join', term: 'Natural join (⋈)', chapter: 2, def: 'A join on all the attributes two relations share by name: it pairs rows whose shared attributes are equal and shows each shared attribute only once.', related: ['theta-join', 'outer-join'], see: [{ lesson: 'rel-algebra-join' }, { lesson: 'int-joins' }], example: 'select title, name from production natural join company order by title limit 5;' },
    { id: 'outer-join', term: 'Outer join', chapter: 4, def: 'A join that keeps rows which found no match as well, filling the missing side\'s columns with nulls. A left outer join keeps every row of the left input, a right outer join every row of the right, and a full outer join both.', related: ['natural-join'], see: [{ lesson: 'int-outer' }], example: 'select pa.name, b.booking_id from patron pa left join booking b on b.patron_id = pa.patron_id where b.booking_id is null;' },
    { id: 'division', term: 'Division (÷)', chapter: 2, def: 'An algebra operator for questions of the form "which x are related to all y?": r ÷ s returns each value t for which every row of s, combined with t, appears in r. SQL usually expresses it with a double `NOT EXISTS` or with `EXCEPT`.', related: ['relational-algebra'], see: [{ lesson: 'sql-subq-more' }] },
    { id: 'rename', term: 'Rename (ρ)', chapter: 2, def: 'The algebra operator that gives a relation, or some of its attributes, a different name. It is what lets a relation be combined with a second copy of itself.', related: ['relational-algebra'], see: [{ lesson: 'rel-algebra-join' }] },
    { id: 'tuple-relational-calculus', term: 'Tuple relational calculus', chapter: 27, def: 'A declarative query language based on logic: a query { t | P(t) } describes the rows t that make the formula P true, with variables that stand for whole rows.', related: ['domain-relational-calculus', 'safe-expression'] },
    { id: 'domain-relational-calculus', term: 'Domain relational calculus', chapter: 27, def: 'A logic-based query language like the tuple calculus, except that its variables stand for individual attribute values rather than entire rows.', related: ['tuple-relational-calculus', 'safe-expression'] },
    { id: 'safe-expression', term: 'Safe expression', chapter: 27, def: 'A calculus query whose result can only contain values found in the database or written in the query itself, which guarantees a finite answer.', related: ['tuple-relational-calculus'] },

    // ---- 3-5: SQL ----
    { id: 'three-valued-logic', term: 'Three-valued logic', chapter: 3, def: 'Logic with a third truth value, *unknown*, alongside true and false; comparisons involving null produce it. A `WHERE` clause keeps a row only if its condition is true, so unknown behaves like false there.', related: ['null'], see: [{ lesson: 'sql-nulls' }], example: 'select null = null as eq, null is null as is_null, (null and false) as and_false, (null or true) as or_true;' },
    { id: 'aggregate-function', term: 'Aggregate function', chapter: 3, def: 'A function that reduces many values to one, such as `count`, `sum`, `avg`, `min` and `max`. With `GROUP BY` it produces one result for each group.', related: ['group-by', 'window-function'], see: [{ lesson: 'sql-aggregates' }], example: 'select genre, count(*), avg(runtime_min) from production group by genre order by 1;' },
    { id: 'group-by', term: 'Grouping', chapter: 3, def: 'Splitting the rows of a query into groups that share the same values in the `GROUP BY` expressions, so aggregates give one answer per group. `HAVING` then decides which groups to keep.', related: ['aggregate-function'], see: [{ lesson: 'sql-aggregates' }] },
    { id: 'subquery', term: 'Nested subquery', chapter: 3, def: 'A query written inside another statement. It can supply a set to test against (`IN`, `EXISTS`, `ANY`, `ALL`), a single value, or a table in `FROM`.', related: ['correlated-subquery', 'scalar-subquery'], see: [{ lesson: 'sql-subq-membership' }] },
    { id: 'correlated-subquery', term: 'Correlated subquery', chapter: 3, def: 'A subquery that mentions a column of the query around it, so its answer depends on the current outer row and, taken literally, is recomputed for each one. Optimizers often rewrite it as a join.', related: ['subquery'], see: [{ lesson: 'sql-subq-membership' }], example: 'select title, genre, runtime_min from production p where runtime_min > (select avg(runtime_min) from production q where q.genre = p.genre);' },
    { id: 'scalar-subquery', term: 'Scalar subquery', chapter: 3, def: 'A subquery used where a single value is expected; it must produce at most one row with one column. No rows gives null, and more than one row is an error.', related: ['subquery'], see: [{ lesson: 'sql-subq-more' }] },
    { id: 'set-operations', term: 'Set operations', chapter: 3, def: '`UNION`, `INTERSECT` and `EXCEPT`, which merge the results of two queries with matching columns as sets. They discard duplicate rows unless you add `ALL`.', related: ['relational-algebra'], see: [{ lesson: 'sql-setops' }] },
    { id: 'multiset', term: 'Multiset (bag)', chapter: 3, def: 'A collection in which the same element may occur several times, and the number of occurrences matters. SQL tables and query results behave as multisets unless a key or `DISTINCT` prevents duplicates.', related: ['relation', 'projection'] },
    { id: 'view', term: 'View', chapter: 4, def: 'A stored query given a name, which can be queried as if it were a table. Its rows are worked out from the underlying tables each time it is used.', related: ['materialized-view', 'levels-of-abstraction'], see: [{ lesson: 'int-views' }] },
    { id: 'materialized-view', term: 'Materialized view', chapter: 4, def: 'A view whose result is actually computed and saved. Reading it is as quick as reading a table, but the saved rows fall out of date when the underlying tables change, until it is refreshed.', related: ['view', 'view-maintenance'], see: [{ lesson: 'int-views' }] },
    { id: 'view-maintenance', term: 'View maintenance', chapter: 16, def: 'The work of bringing a materialized view up to date after its source tables change. Incremental maintenance works out how the view changes from the changes to its inputs, rather than recomputing the whole result.', related: ['materialized-view'] },
    { id: 'integrity-constraint', term: 'Integrity constraint', chapter: 4, def: 'A rule the stored data must always obey, such as `NOT NULL`, `UNIQUE`, `CHECK`, a primary or foreign key, or an assertion. The database refuses any change that would break it.', related: ['check-constraint', 'referential-integrity', 'assertion'], see: [{ lesson: 'int-constraints' }] },
    { id: 'check-constraint', term: 'Check constraint', chapter: 4, def: 'A condition attached to a table that each row must not violate, for example `check (seats between 1 and 8)`. A row whose condition is false is refused; one whose condition is unknown because of a null is accepted.', related: ['integrity-constraint'], see: [{ lesson: 'int-constraints' }] },
    { id: 'assertion', term: 'Assertion', chapter: 4, def: 'A condition about the database as a whole, possibly spanning several tables, that must be true at all times. Few systems implement general assertions, since checking them after every change can be expensive.', related: ['integrity-constraint', 'trigger'] },
    { id: 'deferred-constraint', term: 'Deferred constraint', chapter: 4, def: 'A constraint that is checked when the transaction commits rather than after each statement, so the data may break it temporarily in the middle of a transaction.', related: ['integrity-constraint'], see: [{ lesson: 'int-fk' }] },
    { id: 'authorization', term: 'Authorization', chapter: 4, def: 'Control over who may do what in a database. Privileges such as reading, inserting, updating or deleting are given to users or roles on particular objects with `GRANT` and withdrawn with `REVOKE`.', related: ['role'], see: [{ lesson: 'int-auth' }] },
    { id: 'role', term: 'Role', chapter: 4, def: 'A named bundle of privileges. A user who is granted the role gets everything the role is allowed to do.', related: ['authorization'], see: [{ lesson: 'int-auth' }] },
    { id: 'trigger', term: 'Trigger', chapter: 5, def: 'A routine the database runs automatically in response to a change to a table (an insert, update or delete), either before or after it, and either for each affected row or once per statement.', related: ['stored-procedure', 'assertion'] },
    { id: 'stored-procedure', term: 'Stored procedure', chapter: 5, def: 'A routine saved inside the database and executed by the server, written in SQL or a procedural extension such as PL/pgSQL or SQL/PSM.', related: ['trigger'] },
    { id: 'recursive-query', term: 'Recursive query', chapter: 5, def: 'A query that refers to its own result, written with `WITH RECURSIVE`. It begins with a starting set of rows and keeps adding rows derived from the previous step until no new ones appear, for example following a chain of productions each adapted from the one before.', related: ['transitive-closure'], example: 'with recursive src(prod_id, source_id) as (select prod_id, based_on from production where based_on is not null union select s.prod_id, p.based_on from src s join production p on p.prod_id = s.source_id where p.based_on is not null) select * from src order by 1, 2;' },
    { id: 'transitive-closure', term: 'Transitive closure', chapter: 5, def: 'For a relation of direct links, the set of all pairs (a, b) such that b can be reached from a by following one or more links. Basic relational algebra cannot express it for paths of unknown length; a recursive query can.', related: ['recursive-query'] },
    { id: 'window-function', term: 'Window function', chapter: 5, def: 'A function evaluated for each row over a group of nearby or related rows, its window, while still returning every row. Ranks, running totals and moving averages are typical uses.', related: ['aggregate-function', 'olap'], example: 'select billed_as, company_id, fee, rank() over (partition by company_id order by fee desc) from artist order by company_id, 4;' },
    { id: 'olap', term: 'OLAP', chapter: 11, def: 'Online analytical processing: exploring summarized data interactively along several dimensions, zooming out to totals (roll-up), into detail (drill-down), or fixing some dimensions to look at a slice.', related: ['data-cube', 'data-warehouse'] },
    { id: 'data-cube', term: 'Data cube', chapter: 11, def: 'A measure aggregated over every combination of a chosen set of dimensions, including the totals where a dimension is left out. SQL produces it with `GROUP BY CUBE`; `ROLLUP` produces only the totals of a hierarchy.', related: ['olap'], example: 'select pr.genre, s.kind, count(*) from performance f join production pr using (prod_id) join stage s using (venue_code, stage_no) group by cube (pr.genre, s.kind) order by 1, 2;' },
    { id: 'data-warehouse', term: 'Data warehouse', chapter: 11, def: 'A database built for analysis that collects and integrates data from many operational systems, usually organized around fact tables and dimension tables.', related: ['olap', 'star-schema'] },
    { id: 'star-schema', term: 'Star schema', chapter: 11, def: 'A warehouse design with one central fact table holding measurements and foreign keys, surrounded by smaller dimension tables (such as date, venue or product) that describe them.', related: ['data-warehouse'] },

    // ---- 6: E-R model ----
    { id: 'entity-set', term: 'Entity set', chapter: 6, def: 'All the things of one kind that a design keeps track of, such as every venue or every patron. In an E-R diagram it is a rectangle.', related: ['relationship-set', 'weak-entity-set'], see: [{ view: 'er', label: 'E-R diagram' }] },
    { id: 'relationship-set', term: 'Relationship set', chapter: 6, def: 'A collection of links that each connect entities from given entity sets, such as which patron booked which performance. In an E-R diagram it is a diamond.', related: ['entity-set', 'mapping-cardinality'], see: [{ view: 'er', label: 'E-R diagram' }] },
    { id: 'mapping-cardinality', term: 'Mapping cardinality', chapter: 6, def: 'A limit on how many entities on one side of a relationship set an entity on the other side may be linked to: one-to-one, one-to-many, many-to-one or many-to-many.', related: ['participation', 'relationship-set'], see: [{ view: 'er', label: 'E-R diagram' }] },
    { id: 'participation', term: 'Participation', chapter: 6, def: 'Whether every entity of a set must appear in a relationship set (total participation, drawn with a double line) or only some need to (partial participation).', related: ['mapping-cardinality'], see: [{ view: 'er', label: 'E-R diagram' }] },
    { id: 'weak-entity-set', term: 'Weak entity set', chapter: 6, def: 'An entity set whose members cannot be told apart by their own attributes, only together with the entity they belong to, such as stage 2 of a particular venue.', related: ['discriminator', 'identifying-relationship'], see: [{ view: 'er', label: 'E-R diagram' }] },
    { id: 'discriminator', term: 'Discriminator (partial key)', chapter: 6, def: 'The attributes that distinguish the weak entities belonging to the same owner, such as a stage number within one venue. The owner\'s key together with the discriminator identifies a weak entity.', related: ['weak-entity-set'] },
    { id: 'identifying-relationship', term: 'Identifying relationship', chapter: 6, def: 'The relationship set that connects a weak entity set to the entity set that owns it. Every weak entity takes part in it exactly once. In an E-R diagram it is a double diamond.', related: ['weak-entity-set'] },
    { id: 'composite-attribute', term: 'Composite attribute', chapter: 6, def: 'An attribute that is built from smaller parts, such as a full name made of a given name and a family name. When converted to tables it is usually stored as its separate parts.', related: ['multivalued-attribute', 'derived-attribute'] },
    { id: 'multivalued-attribute', term: 'Multivalued attribute', chapter: 6, def: 'An attribute that can hold several values for one entity, such as all the phone numbers of a patron. When converted to tables it becomes a relation of its own. In an E-R diagram it is written in braces.', related: ['composite-attribute'] },
    { id: 'derived-attribute', term: 'Derived attribute', chapter: 6, def: 'An attribute whose value can be calculated from others, such as an age from a birth date, so it normally is not stored.', related: ['composite-attribute'] },
    { id: 'specialization', term: 'Specialization', chapter: 6, def: 'Splitting an entity set into subgroups that have attributes or relationships of their own, working from general to specific: for example artists and patrons as kinds of person. The subgroups may overlap or be disjoint.', related: ['generalization', 'aggregation'] },
    { id: 'generalization', term: 'Generalization', chapter: 6, def: 'Working from specific to general: noticing that several entity sets share features and combining them under a common higher-level entity set, whose attributes they inherit.', related: ['specialization'] },
    { id: 'aggregation', term: 'Aggregation (E-R)', chapter: 6, def: 'Treating a relationship set, together with the entity sets it connects, as if it were an entity, so that another relationship set can refer to it.', related: ['relationship-set'] },

    // ---- 7: normalization ----
    { id: 'functional-dependency', term: 'Functional dependency', chapter: 7, def: 'A constraint α → β: whenever two rows agree on the attributes α, they also agree on the attributes β. It must hold in every legal state of the relation, not just the current one.', related: ['trivial-fd', 'closure-attributes', 'superkey'] },
    { id: 'trivial-fd', term: 'Trivial functional dependency', chapter: 7, def: 'A dependency α → β where β is part of α. It is true of every relation and tells you nothing.', related: ['functional-dependency'] },
    { id: 'armstrong-axioms', term: 'Armstrong\'s axioms', chapter: 7, def: 'Three inference rules for functional dependencies: reflexivity, augmentation and transitivity. Every dependency they derive really follows from the starting set, and every dependency that follows can be derived with them.', related: ['closure-fd-set', 'functional-dependency'] },
    { id: 'closure-fd-set', term: 'Closure of a set of FDs (F⁺)', chapter: 7, def: 'The set F⁺ of all functional dependencies that logically follow from a given set F. It is usually very large, so attribute closures are used instead to answer questions about it.', related: ['armstrong-axioms', 'closure-attributes'] },
    { id: 'closure-attributes', term: 'Attribute closure (α⁺)', chapter: 7, def: 'The set α⁺ of every attribute whose value is fixed once the values of α are known, given the dependencies F. α is a superkey exactly when α⁺ includes all attributes of the relation.', related: ['closure-fd-set', 'superkey'] },
    { id: 'extraneous-attribute', term: 'Extraneous attribute', chapter: 7, def: 'An attribute in a functional dependency that can be dropped from it without changing which dependencies follow from the whole set.', related: ['canonical-cover'] },
    { id: 'canonical-cover', term: 'Canonical cover', chapter: 7, def: 'A simplified set of functional dependencies with exactly the same consequences as F: no dependency has an extraneous attribute, and no two dependencies have the same left side. The 3NF synthesis algorithm starts from it.', related: ['extraneous-attribute', '3nf'] },
    { id: 'lossless-decomposition', term: 'Lossless decomposition', chapter: 7, def: 'Splitting a relation into smaller ones in such a way that joining them back together always reproduces exactly the original rows, never extra ones. A split into two parts is lossless when their common attributes form a superkey of one of the parts.', related: ['dependency-preservation', 'natural-join'] },
    { id: 'dependency-preservation', term: 'Dependency preservation', chapter: 7, def: 'A property of a decomposition: every original functional dependency can still be enforced by checking the smaller relations one at a time, without joining them.', related: ['lossless-decomposition', 'bcnf'] },
    { id: '1nf', term: 'First normal form (1NF)', chapter: 7, def: 'A relation is in first normal form when every attribute holds single, indivisible values, never lists, sets or nested records.', related: ['atomic-domain', '2nf'] },
    { id: '2nf', term: 'Second normal form (2NF)', chapter: 7, def: 'A relation is in second normal form when it is in 1NF and no attribute outside the candidate keys depends on only part of a candidate key. It matters mainly as a step on the way to 3NF.', related: ['1nf', '3nf'] },
    { id: '3nf', term: 'Third normal form (3NF)', chapter: 7, def: 'A relation is in third normal form when for every nontrivial dependency α → β that holds, either α is a superkey or every attribute of β that is not in α belongs to some candidate key. Any relation can be split into 3NF relations without loss and without losing dependencies.', related: ['bcnf', 'canonical-cover'] },
    { id: 'bcnf', term: 'Boyce-Codd normal form (BCNF)', chapter: 7, def: 'A relation is in Boyce-Codd normal form when the left side of every nontrivial functional dependency that holds on it is a superkey. It leaves no redundancy caused by functional dependencies, but reaching it can make some dependencies impossible to check without a join.', related: ['3nf', 'dependency-preservation'] },
    { id: 'multivalued-dependency', term: 'Multivalued dependency', chapter: 7, def: 'A constraint α ↠ β: for a fixed value of α, the set of β values and the set of values of the other attributes are independent, so every combination of the two appears.', related: ['4nf', 'functional-dependency'] },
    { id: '4nf', term: 'Fourth normal form (4NF)', chapter: 7, def: 'A relation is in fourth normal form when the left side of every nontrivial multivalued dependency that holds on it is a superkey. A relation in 4NF is also in BCNF.', related: ['multivalued-dependency', 'bcnf'] },
    { id: 'join-dependency', term: 'Join dependency', chapter: 7, def: 'A constraint that a relation is always equal to the join of its projections onto certain sets of attributes. Fifth normal form (project-join normal form) is defined in terms of it.', related: ['multivalued-dependency'] },
    { id: 'denormalization', term: 'Denormalization', chapter: 7, def: 'Deliberately storing some data more than once, for example keeping a joined result as a table, so that frequent queries run faster. The cost is extra work to keep the copies in agreement.', related: ['materialized-view', 'bcnf'] },

    // ---- 8-11: complex types, applications, big data ----
    { id: 'json', term: 'JSON', chapter: 8, def: 'A text notation for data made of objects (key and value pairs), arrays and simple values, which can nest. Databases offer column types such as `jsonb` and operators for reaching into it.', related: ['semi-structured-data'] },
    { id: 'semi-structured-data', term: 'Semi-structured data', chapter: 8, def: 'Data in which each record describes its own structure, so records need not all follow one fixed schema. JSON and XML documents are common examples.', related: ['json'] },
    { id: 'sql-injection', term: 'SQL injection', chapter: 9, def: 'An attack in which text supplied by a user is pasted into a SQL statement and changes what the statement does. Passing values as parameters of a prepared statement prevents it.', related: ['prepared-statement'] },
    { id: 'prepared-statement', term: 'Prepared statement', chapter: 5, def: 'A statement sent to the database once, with placeholders for values, then executed many times with different values filled in. The values are never read as SQL.', related: ['sql-injection'] },
    { id: 'key-value-store', term: 'Key-value store', chapter: 10, def: 'A storage system offering little more than putting a value under a key and getting it back by that key. The values are opaque to the system, which spreads and copies them over many machines.', related: ['partitioning', 'replication'] },
    { id: 'mapreduce', term: 'MapReduce', chapter: 10, def: 'A framework for batch processing on many machines: a map step turns each input record into key and value pairs, the framework collects the pairs by key, and a reduce step combines the values for each key.', related: ['shared-nothing', 'partitioning'], see: [{ view: 'mapreduce', label: 'MapReduce' }] },

    // ---- 12-13: storage ----
    { id: 'seek-time', term: 'Seek time', chapter: 12, def: 'On a magnetic disk, the time the arm needs to move the read and write head to the right track. It is the main cost of reading scattered blocks.', related: ['rotational-latency', 'block'], see: [{ view: 'disk', label: 'Disk' }] },
    { id: 'rotational-latency', term: 'Rotational latency', chapter: 12, def: 'On a magnetic disk, the wait after a seek until the wanted sector turns under the head. On average it is half the time of one rotation.', related: ['seek-time'], see: [{ view: 'disk', label: 'Disk' }] },
    { id: 'raid', term: 'RAID', chapter: 12, def: 'Combining several disks into one unit. Spreading data across them (striping) makes access faster, and storing mirror copies or parity lets the data survive the loss of a disk.', related: ['seek-time'] },
    { id: 'block', term: 'Block', chapter: 12, def: 'The fixed-size chunk, typically a few kilobytes, in which data moves between disk and memory. Query costs are usually measured by counting the blocks read and written and the seeks needed.', related: ['page', 'buffer-manager'], see: [{ view: 'disk', label: 'Disk' }] },
    { id: 'page', term: 'Page', chapter: 13, def: 'A block as the database lays it out internally: a header followed by rows or index entries. In Kwery the page size is set per database and is 4096 bytes unless you choose another.', related: ['block', 'slotted-page'], see: [{ view: 'storage', label: 'Storage' }] },
    { id: 'slotted-page', term: 'Slotted page', chapter: 13, def: 'A page layout in which a table of slots near the start points at records placed from the end of the page backwards. A record can move within the page without its slot number, and so its address, changing.', related: ['page', 'tid'], see: [{ view: 'storage', label: 'Storage' }] },
    { id: 'record', term: 'Record', chapter: 13, def: 'The bytes that store one row on a page: a small header followed by the attribute values. A value of varying length is reached through its offset and length.', related: ['slotted-page', 'tid'], see: [{ view: 'storage', label: 'Storage' }] },
    { id: 'tid', term: 'Record identifier (TID, RID)', chapter: 13, def: 'The physical address of a stored row: the number of its block and its slot within that block. Indexes use it to point at rows; in Kwery and PostgreSQL it is the column `ctid`.', related: ['slotted-page', 'secondary-index'], see: [{ view: 'storage', label: 'Storage' }], example: 'select ctid, * from venue limit 5;' },
    { id: 'heap-file', term: 'Heap file', chapter: 13, def: 'A file organization with no ordering: a new row may be placed in any block with free space. Locating rows by value therefore needs a full scan or an index.', related: ['sequential-file', 'free-space-map'], see: [{ view: 'storage', label: 'Storage' }] },
    { id: 'free-space-map', term: 'Free-space map', chapter: 13, def: 'A compact record of roughly how much room is left in each block of a heap file, so an insert can quickly find a block it fits into.', related: ['heap-file'] },
    { id: 'sequential-file', term: 'Sequential file', chapter: 13, def: 'A file in which records are kept sorted by a search key. Reading in key order is cheap, but keeping the order while inserting is more work.', related: ['heap-file', 'clustering-index'] },
    { id: 'multitable-clustering', term: 'Multitable clustering', chapter: 13, def: 'Placing rows from different relations that are often joined in the same blocks, for example a venue\'s row next to the rows of its stages, so the join reads fewer blocks.', related: ['heap-file'] },
    { id: 'column-store', term: 'Column-oriented storage', chapter: 13, def: 'Storing a table one column at a time instead of one row at a time. A query that needs only a few columns reads only those, and a column of similar values compresses well.', related: ['olap'] },
    { id: 'buffer-manager', term: 'Buffer manager', chapter: 13, def: 'The component that keeps copies of disk blocks in memory. When a block is requested it either finds it already in memory or reads it from disk, choosing a frame to reuse if memory is full.', related: ['pinned-block', 'replacement-policy', 'buffer-pool'], see: [{ view: 'buffer', label: 'Buffer pool' }] },
    { id: 'buffer-pool', term: 'Buffer pool', chapter: 13, def: 'The area of memory, divided into frames of one block each, where the buffer manager keeps blocks. Finding a block there is a hit; having to read it from disk is a miss.', related: ['buffer-manager'], see: [{ view: 'buffer', label: 'Buffer pool' }] },
    { id: 'pinned-block', term: 'Pinned block', chapter: 13, def: 'A block in the buffer pool that some operation is currently using, so it may not be evicted. A pin count says how many users currently hold it.', related: ['buffer-manager'], see: [{ view: 'buffer', label: 'Buffer pool' }] },
    { id: 'replacement-policy', term: 'Replacement policy', chapter: 13, def: 'The rule the buffer manager uses to choose which unpinned frame to reuse when it needs room: least recently used (LRU), most recently used (MRU, useful for repeated scans), the clock approximation of LRU, and others.', related: ['buffer-manager', 'clock-algorithm'], see: [{ view: 'buffer', label: 'Buffer pool' }] },
    { id: 'clock-algorithm', term: 'Clock algorithm', chapter: 13, def: 'An inexpensive stand-in for LRU replacement: the frames form a circle with a hand pointing at one; the hand moves on, clearing each frame\'s reference bit, until it reaches an unpinned frame whose bit was already clear, and reuses that frame.', related: ['replacement-policy'], see: [{ view: 'buffer', label: 'Buffer pool' }] },
    { id: 'dirty-page', term: 'Dirty page', chapter: 13, def: 'A page in memory that has been changed since it was read from disk. It has to be written back before its frame can be used for another page.', related: ['buffer-manager', 'steal'], see: [{ view: 'buffer', label: 'Buffer pool' }] },

    // ---- 14: indexing ----
    { id: 'search-key', term: 'Search key', chapter: 14, def: 'The column or columns an index is organized by and can look up. A search key does not have to be unique.', related: ['ordered-index'], see: [{ lesson: 'int-indexes' }] },
    { id: 'ordered-index', term: 'Ordered index', chapter: 14, def: 'An index that keeps its entries sorted by search key, so it can find both exact values and ranges of values.', related: ['b-plus-tree', 'hash-index'], see: [{ view: 'index', label: 'Index' }] },
    { id: 'clustering-index', term: 'Clustering (primary) index', chapter: 14, def: 'An index on the same key that the table\'s rows are physically sorted by. Because the rows can be in only one order, a table has at most one such index.', related: ['secondary-index', 'sequential-file'] },
    { id: 'secondary-index', term: 'Secondary (nonclustering) index', chapter: 14, def: 'An index whose order differs from the physical order of the rows. It needs an entry for every row, and reading a range through it may visit a different block for each row.', related: ['clustering-index', 'dense-index'] },
    { id: 'dense-index', term: 'Dense index', chapter: 14, def: 'An index that has an entry for every search-key value that occurs in the file.', related: ['sparse-index'] },
    { id: 'sparse-index', term: 'Sparse index', chapter: 14, def: 'An index with entries for only some search-key values, typically the first one in each block. It only works when the file is sorted on that key.', related: ['dense-index', 'clustering-index'] },
    { id: 'b-plus-tree', term: 'B+ tree', chapter: 14, def: 'A balanced tree index in which every key, with a pointer to its row, sits in a leaf, the leaves are chained in key order, and the inner nodes hold only keys that guide the search. All leaves are at the same depth.', related: ['fan-out', 'node-split', 'leaf-node'], see: [{ view: 'index', label: 'Index' }, { view: 'indexlab', label: 'Index playground' }, { lesson: 'int-indexes' }] },
    { id: 'fan-out', term: 'Fan-out', chapter: 14, def: 'How many children an inner node of a tree index has. A large fan-out keeps the tree shallow: with a few hundred children per node, even a huge table needs only three or four levels.', related: ['b-plus-tree'], see: [{ view: 'index', label: 'Index' }] },
    { id: 'leaf-node', term: 'Leaf node', chapter: 14, def: 'A node at the bottom level of a B+ tree. It holds search keys with pointers to the rows, plus a link to the next leaf so ranges can be read in order.', related: ['b-plus-tree'], see: [{ view: 'index', label: 'Index' }] },
    { id: 'node-split', term: 'Node split', chapter: 14, def: 'What happens when an insert overfills a B+ tree node: its entries are divided between two nodes and a separating key is added to the parent. Splitting the root makes the tree one level taller.', related: ['b-plus-tree', 'coalescing'], see: [{ view: 'indexlab', label: 'Index playground' }] },
    { id: 'coalescing', term: 'Coalescing', chapter: 14, def: 'What happens when a delete leaves a B+ tree node with too few entries: it either combines with a neighbour or takes some entries from it, and the parent\'s separating keys are adjusted.', related: ['node-split', 'b-plus-tree'], see: [{ view: 'indexlab', label: 'Index playground' }] },
    { id: 'bulk-loading', term: 'Bulk loading', chapter: 14, def: 'Building an index from a large set of entries in one go: sort the entries, then fill the leaves from left to right and build the upper levels above them. It is far quicker than inserting entries one by one.', related: ['b-plus-tree'] },
    { id: 'covering-index', term: 'Covering index', chapter: 14, def: 'An index that contains every column a query uses, so the query can be answered by reading only the index, without visiting the table (an index-only scan).', related: ['secondary-index'], see: [{ view: 'plan', label: 'Plan' }] },
    { id: 'hash-index', term: 'Hash index', chapter: 14, def: 'An index that places each entry in a bucket chosen by applying a hash function to its key. Looking up an exact key usually takes about one block read, but it cannot answer range queries.', related: ['bucket-overflow', 'extendable-hashing'], see: [{ view: 'indexlab', label: 'Index playground' }] },
    { id: 'bucket-overflow', term: 'Bucket overflow', chapter: 14, def: 'When a hash bucket receives more entries than its block can hold, because the keys are unevenly distributed or there are too few buckets. The extra entries go to chained overflow blocks, which slow lookups.', related: ['hash-index', 'extendable-hashing'], see: [{ view: 'indexlab', label: 'Index playground' }] },
    { id: 'extendable-hashing', term: 'Extendable hashing', chapter: 14, def: 'A hash index that grows smoothly: a directory, indexed by a prefix of the hash value\'s bits, points to buckets. A full bucket splits on its own, and the directory doubles only when the split needs one more bit.', related: ['hash-index'], see: [{ view: 'indexlab', label: 'Index playground' }] },
    { id: 'bitmap-index', term: 'Bitmap index', chapter: 14, def: 'An index that keeps, for each distinct value of a column, a sequence of bits with one bit per row saying whether that row has the value. Conditions on several columns are answered by combining the bitmaps with AND and OR.', related: ['secondary-index'], see: [{ view: 'indexlab', label: 'Index playground' }] },
    { id: 'lsm-tree', term: 'Log-structured merge tree (LSM tree)', chapter: 14, def: 'An index designed for heavy writing: new entries go into a sorted structure in memory, which is written to disk as a sorted run when it fills, and runs are merged in the background into fewer, larger ones.', related: ['bloom-filter', 'b-plus-tree'], see: [{ view: 'indexlab', label: 'Index playground' }] },
    { id: 'bloom-filter', term: 'Bloom filter', chapter: 14, def: 'A compact array of bits plus several hash functions, used to test whether a key might be in a set. A no is always correct; a yes may occasionally be wrong (a false positive).', related: ['lsm-tree'], see: [{ view: 'bloom', label: 'Bloom filter' }] },
    { id: 'r-tree', term: 'R-tree', chapter: 14, def: 'A balanced tree index for spatial data in which each node stores rectangles that enclose everything in the subtree below them, so a search can skip subtrees that cannot overlap the region asked for.', related: ['b-plus-tree'], see: [{ view: 'indexlab', label: 'Index playground' }] },

    // ---- 15-16: query processing and optimization ----
    { id: 'query-plan', term: 'Query evaluation plan', chapter: 15, def: 'The concrete recipe the system follows to answer a query: a tree of operators, each with a specific algorithm, such as an index scan feeding a hash join. `EXPLAIN` displays the plan that was chosen.', related: ['cost-model', 'pipelining'], see: [{ view: 'plan', label: 'Plan' }] },
    { id: 'cost-model', term: 'Cost model', chapter: 15, def: 'The set of formulas an optimizer uses to predict how expensive a plan will be, from statistics about the data. Kwery counts the blocks transferred and the disk seeks.', related: ['query-plan', 'cardinality-estimation'], see: [{ view: 'plan', label: 'Plan' }] },
    { id: 'selectivity', term: 'Selectivity', chapter: 16, def: 'The share of rows that pass a condition, between 0 and 1. The optimizer estimates it from statistics, and it often decides whether an index or a full scan is cheaper.', related: ['cardinality-estimation', 'histogram'], see: [{ view: 'plan', label: 'Plan' }] },
    { id: 'cardinality-estimation', term: 'Cardinality estimation', chapter: 16, def: 'Predicting the number of rows each operator in a plan will produce. Bad estimates are the most frequent cause of a poor plan choice.', related: ['selectivity', 'statistics'], see: [{ view: 'plan', label: 'Plan' }] },
    { id: 'statistics', term: 'Statistics', chapter: 16, def: 'Summary numbers the optimizer keeps for each table and column: row and block counts, the number of distinct values, the most common values and histograms. `ANALYZE` collects them.', related: ['histogram', 'cardinality-estimation'] },
    { id: 'histogram', term: 'Histogram', chapter: 16, def: 'A summary of how a column\'s values are spread, made by dividing them into buckets. It lets the optimizer estimate range conditions better than if it assumed values were spread evenly.', related: ['statistics', 'selectivity'] },
    { id: 'nested-loop-join', term: 'Nested-loop join', chapter: 15, def: 'The simplest join algorithm: for every row of the outer input, read through the entire inner input and output each pair that satisfies the join condition. It handles any condition but can cost one scan of the inner input per outer row.', related: ['block-nested-loop-join', 'indexed-nested-loop-join'], see: [{ view: 'plan', label: 'Plan' }] },
    { id: 'block-nested-loop-join', term: 'Block nested-loop join', chapter: 15, def: 'A nested-loop join that takes the outer input a block, or a memory-load of blocks, at a time, and scans the inner input once for each such chunk rather than once for each outer row.', related: ['nested-loop-join'], see: [{ view: 'plan', label: 'Plan' }] },
    { id: 'indexed-nested-loop-join', term: 'Indexed nested-loop join', chapter: 15, def: 'A nested-loop join in which, for each outer row, an index on the inner input is used to find the matching rows instead of scanning the whole inner input.', related: ['nested-loop-join'], see: [{ view: 'plan', label: 'Plan' }] },
    { id: 'merge-join', term: 'Merge join', chapter: 15, def: 'An equality join of two inputs that are both sorted on the join columns: the two are read side by side in a single pass, and rows with equal keys are paired up.', related: ['external-sort-merge', 'hash-join'], see: [{ view: 'plan', label: 'Plan' }] },
    { id: 'hash-join', term: 'Hash join', chapter: 15, def: 'An equality join that loads one input into a hash table keyed on the join columns and then looks up each row of the other input in it. If the table would not fit in memory, both inputs are first split into matching partitions with the same hash function.', related: ['build-input', 'recursive-partitioning'], see: [{ view: 'plan', label: 'Plan' }] },
    { id: 'build-input', term: 'Build and probe inputs', chapter: 15, def: 'The two roles in a hash join: the build input is the one loaded into the in-memory hash table, and the probe input is the one whose rows look up matches in it. The smaller input is the better choice to build on.', related: ['hash-join'], see: [{ view: 'plan', label: 'Plan' }] },
    { id: 'recursive-partitioning', term: 'Recursive partitioning', chapter: 15, def: 'In a hash join, splitting a partition into smaller pieces with a different hash function when it is still too large to fit in memory.', related: ['hash-join'] },
    { id: 'external-sort-merge', term: 'External sort-merge', chapter: 15, def: 'A way to sort more data than fits in memory: sort it in memory-sized pieces, write each out as a sorted run, then repeatedly merge several runs into one until a single run is left.', related: ['run', 'merge-join'], see: [{ view: 'plan', label: 'Plan' }] },
    { id: 'run', term: 'Run', chapter: 15, def: 'A sorted segment of the data produced during an external sort, which is later merged with other runs.', related: ['external-sort-merge'] },
    { id: 'pipelining', term: 'Pipelining', chapter: 15, def: 'Handing each row an operator produces directly to the next operator, instead of first saving the whole intermediate result. A sort or the building of a hash table interrupts the pipeline, since it must see all its input first.', related: ['materialization', 'query-plan'], see: [{ view: 'plan', label: 'Plan' }] },
    { id: 'materialization', term: 'Materialization', chapter: 15, def: 'Computing an operator\'s entire result and saving it, possibly to disk, before the operator that consumes it starts.', related: ['pipelining'] },
    { id: 'equivalence-rules', term: 'Equivalence rules', chapter: 16, def: 'Rules for rewriting a relational algebra expression into a different one that returns the same result on every possible database, for example applying a selection before a join rather than after it.', related: ['join-ordering'], see: [{ view: 'algebra', label: 'Relational algebra' }] },
    { id: 'join-ordering', term: 'Join ordering', chapter: 16, def: 'Deciding in which sequence to join several relations. Because joins can be reordered freely, there are many possible orders, and their costs can differ enormously.', related: ['left-deep-tree', 'dynamic-programming-optimizer'], see: [{ view: 'plan', label: 'Plan' }] },
    { id: 'left-deep-tree', term: 'Left-deep join tree', chapter: 16, def: 'A join tree in which the right-hand input of every join is a base table rather than another join. Limiting the search to such trees makes optimization cheaper and suits pipelined execution.', related: ['join-ordering'], see: [{ view: 'plan', label: 'Plan' }] },
    { id: 'dynamic-programming-optimizer', term: 'Dynamic-programming optimizer', chapter: 16, def: 'An optimizer that finds the cheapest plan for each subset of the relations to be joined, starting with single relations and building larger subsets from the best plans of smaller ones.', related: ['join-ordering', 'cost-model'], see: [{ view: 'plan', label: 'Plan' }] },

    // ---- 17: transactions ----
    { id: 'transaction', term: 'Transaction', chapter: 17, def: 'A group of database operations that is treated as a single unit of work: either all of its changes are kept (commit) or none of them are (abort).', related: ['acid', 'schedule'], see: [{ lesson: 'int-transactions' }, { view: 'txn', label: 'Transactions' }] },
    { id: 'acid', term: 'ACID', chapter: 17, def: 'Shorthand for the four guarantees a transaction system gives: atomicity, consistency, isolation and durability.', related: ['atomicity', 'consistency', 'isolation', 'durability'], see: [{ lesson: 'int-transactions' }] },
    { id: 'atomicity', term: 'Atomicity', chapter: 17, def: 'The all-or-nothing guarantee: if a transaction does not finish, every change it made is undone, so the database never keeps only part of it.', related: ['acid', 'undo'], see: [{ view: 'recovery', label: 'Crash and recovery' }] },
    { id: 'consistency', term: 'Consistency', chapter: 17, def: 'The guarantee that a transaction which starts from a correct database and runs by itself also leaves it correct. Writing transactions that do so is the application\'s job; integrity constraints help catch mistakes.', related: ['acid', 'integrity-constraint'] },
    { id: 'isolation', term: 'Isolation', chapter: 17, def: 'The guarantee that transactions running at the same time do not see each other\'s unfinished work, so each behaves as if it had the database to itself, to the extent the chosen isolation level requires.', related: ['acid', 'isolation-level'], see: [{ view: 'txn', label: 'Transactions' }] },
    { id: 'durability', term: 'Durability', chapter: 17, def: 'The guarantee that once a transaction has been reported as committed, its changes will survive any later crash. Writing the log to stable storage before reporting the commit is what provides it.', related: ['acid', 'write-ahead-logging'], see: [{ view: 'log', label: 'Log' }] },
    { id: 'schedule', term: 'Schedule', chapter: 17, def: 'The order in which the operations of several concurrent transactions (reads, writes, commits and aborts) are actually carried out, with each transaction\'s own operations kept in their original order.', related: ['serial-schedule', 'conflict-serializability'], see: [{ view: 'txn', label: 'Transactions' }] },
    { id: 'serial-schedule', term: 'Serial schedule', chapter: 17, def: 'A schedule in which transactions do not interleave: each one runs from start to finish before the next one begins.', related: ['schedule', 'conflict-serializability'], see: [{ view: 'txn', label: 'Transactions' }] },
    { id: 'conflict', term: 'Conflicting operations', chapter: 17, def: 'Two operations from different transactions that access the same data item where at least one is a write. Reversing their order can change the outcome.', related: ['conflict-serializability'], see: [{ view: 'txn', label: 'Transactions' }] },
    { id: 'conflict-serializability', term: 'Conflict serializability', chapter: 17, def: 'A schedule is conflict serializable if it can be turned into a serial schedule just by swapping neighbouring operations that do not conflict. This is the case exactly when its precedence graph contains no cycle.', related: ['precedence-graph', 'view-serializability', 'conflict'], see: [{ view: 'txn', label: 'Transactions' }] },
    { id: 'view-serializability', term: 'View serializability', chapter: 17, def: 'A schedule is view serializable if some serial schedule has the same effect in a specific sense: each read sees the value from the same write, and the same writes are the last ones on each item. It allows more schedules than conflict serializability but is expensive to test.', related: ['conflict-serializability', 'blind-write'] },
    { id: 'blind-write', term: 'Blind write', chapter: 17, def: 'A write to a data item that the writing transaction never read. Any schedule that is view serializable but not conflict serializable contains one.', related: ['view-serializability'] },
    { id: 'precedence-graph', term: 'Precedence graph', chapter: 17, def: 'A directed graph with one node per transaction and an edge from Ti to Tj whenever an operation of Ti conflicts with a later operation of Tj. If it has no cycle, any topological order of its nodes is an equivalent serial order.', related: ['conflict-serializability'], see: [{ view: 'txn', label: 'Transactions' }] },
    { id: 'recoverable-schedule', term: 'Recoverable schedule', chapter: 17, def: 'A schedule in which no transaction commits before every transaction it read uncommitted data from has committed.', related: ['cascadeless-schedule', 'cascading-rollback'], see: [{ view: 'txn', label: 'Transactions' }] },
    { id: 'cascadeless-schedule', term: 'Cascadeless schedule', chapter: 17, def: 'A schedule in which transactions read only data written by transactions that have already committed. Such schedules are always recoverable.', related: ['recoverable-schedule', 'cascading-rollback'], see: [{ view: 'txn', label: 'Transactions' }] },
    { id: 'cascading-rollback', term: 'Cascading rollback', chapter: 17, def: 'A chain of aborts: one transaction fails, so every transaction that read its uncommitted writes must also abort, and then every transaction that read theirs, and so on.', related: ['cascadeless-schedule', 'dirty-read'] },
    { id: 'isolation-level', term: 'Isolation level', chapter: 17, def: 'A setting that says how much a transaction may be affected by others running alongside it. SQL defines read uncommitted, read committed, repeatable read and serializable; choose one with `SET TRANSACTION ISOLATION LEVEL`.', related: ['dirty-read', 'non-repeatable-read', 'phantom'], see: [{ lesson: 'int-transactions' }, { view: 'txn', label: 'Transactions' }] },
    { id: 'dirty-read', term: 'Dirty read', chapter: 17, def: 'Reading data that another transaction has written but not yet committed, and that may therefore still be rolled back.', related: ['isolation-level', 'cascading-rollback'] },
    { id: 'non-repeatable-read', term: 'Non-repeatable read', chapter: 17, def: 'Reading the same row twice within one transaction and getting different values, because another transaction updated it and committed in between.', related: ['isolation-level', 'phantom'] },
    { id: 'phantom', term: 'Phantom', chapter: 17, def: 'A row that shows up, or disappears, when a transaction repeats a query with the same condition, because another transaction has meanwhile inserted or deleted a row matching that condition.', related: ['predicate-lock', 'next-key-locking'], see: [{ view: 'txn', label: 'Transactions' }] },
    { id: 'lost-update', term: 'Lost update', chapter: 17, def: 'An anomaly in which two transactions read the same value and each writes back a new value computed from it, so the second write silently overwrites the first.', related: ['isolation-level'] },
    { id: 'write-skew', term: 'Write skew', chapter: 18, def: 'An anomaly in which two concurrent transactions read overlapping data and then update different rows; each change is fine on its own, but together they break a rule. Snapshot isolation does not prevent it.', related: ['snapshot-isolation', 'ssi'], see: [{ view: 'txn', label: 'Transactions' }] },
    { id: 'snapshot-isolation', term: 'Snapshot isolation', chapter: 18, def: 'A concurrency control scheme in which each transaction reads from a snapshot of the committed data taken when it starts, and when two concurrent transactions write the same item only the one that commits first succeeds. It prevents many anomalies but is not fully serializable.', related: ['mvcc', 'write-skew', 'ssi'], see: [{ view: 'txn', label: 'Transactions' }] },

    // ---- 18: concurrency control ----
    { id: 'lock', term: 'Lock', chapter: 18, def: 'A permission a transaction must hold on a data item before it may access it. The lock manager grants it if it does not clash with locks other transactions already hold on the item; otherwise the requester waits.', related: ['shared-exclusive-lock', 'lock-compatibility', 'two-phase-locking'], see: [{ view: 'txn', label: 'Transactions' }] },
    { id: 'shared-exclusive-lock', term: 'Shared and exclusive locks', chapter: 18, def: 'The two basic lock modes. A shared (S) lock allows reading, and any number of transactions may hold one on the same item; an exclusive (X) lock allows writing, and no other transaction may hold any lock on the item at the same time.', related: ['lock', 'lock-compatibility'], see: [{ view: 'txn', label: 'Transactions' }] },
    { id: 'lock-compatibility', term: 'Lock compatibility', chapter: 18, def: 'A table listing, for each pair of lock modes, whether two different transactions may hold them on the same item at the same time.', related: ['shared-exclusive-lock', 'intention-lock'] },
    { id: 'two-phase-locking', term: 'Two-phase locking (2PL)', chapter: 18, def: 'A locking protocol in which every transaction first acquires locks without releasing any (the growing phase) and then releases locks without acquiring any (the shrinking phase). It guarantees conflict-serializable schedules but not freedom from deadlocks or cascading rollbacks.', related: ['strict-2pl', 'rigorous-2pl', 'lock-point'], see: [{ view: 'txn', label: 'Transactions' }] },
    { id: 'strict-2pl', term: 'Strict two-phase locking', chapter: 18, def: 'Two-phase locking in which exclusive locks are kept until the transaction commits or aborts, so no one can read uncommitted data and schedules are cascadeless.', related: ['two-phase-locking', 'rigorous-2pl'], see: [{ view: 'txn', label: 'Transactions' }] },
    { id: 'rigorous-2pl', term: 'Rigorous two-phase locking', chapter: 18, def: 'Two-phase locking in which every lock, shared or exclusive, is kept until the transaction commits or aborts. The transactions are then serializable in the order they commit.', related: ['strict-2pl'], see: [{ view: 'txn', label: 'Transactions' }] },
    { id: 'lock-point', term: 'Lock point', chapter: 18, def: 'The moment at which a transaction under two-phase locking obtains its final lock. Arranging transactions in the order of their lock points gives an equivalent serial schedule.', related: ['two-phase-locking'] },
    { id: 'lock-upgrade', term: 'Lock conversion', chapter: 18, def: 'Changing the mode of a lock already held: upgrading shared to exclusive (allowed only while still acquiring locks) or downgrading exclusive to shared (allowed only while releasing).', related: ['two-phase-locking', 'shared-exclusive-lock'] },
    { id: 'deadlock', term: 'Deadlock', chapter: 18, def: 'A situation in which each transaction in a group is waiting for a lock that another member of the group holds, so none can ever proceed unless one of them is rolled back.', related: ['wait-for-graph', 'wait-die', 'wound-wait'], see: [{ view: 'txn', label: 'Transactions' }] },
    { id: 'wait-for-graph', term: 'Wait-for graph', chapter: 18, def: 'A directed graph with an edge from Ti to Tj whenever Ti is waiting for a lock held by Tj. A cycle in it means a deadlock, and the system picks a victim to roll back.', related: ['deadlock'], see: [{ view: 'txn', label: 'Transactions' }] },
    { id: 'wait-die', term: 'Wait-die', chapter: 18, def: 'A deadlock prevention rule based on transaction age: an older transaction asking for a lock held by a younger one waits, while a younger one asking for a lock held by an older one is rolled back.', related: ['wound-wait', 'deadlock'] },
    { id: 'wound-wait', term: 'Wound-wait', chapter: 18, def: 'A deadlock prevention rule based on transaction age: an older transaction asking for a lock held by a younger one forces the younger to roll back, while a younger one asking for a lock held by an older one waits.', related: ['wait-die', 'deadlock'] },
    { id: 'lock-timeout', term: 'Lock timeout', chapter: 18, def: 'Dealing with deadlocks by aborting any transaction that has waited for a lock longer than a fixed time. It is easy to implement but may abort transactions that were only slow, not deadlocked.', related: ['deadlock'] },
    { id: 'multiple-granularity', term: 'Multiple granularity locking', chapter: 18, def: 'Locking at different sizes of data arranged in a hierarchy (the whole database, a table, a page, a row), where a lock on a larger unit covers everything inside it.', related: ['intention-lock'], see: [{ view: 'txn', label: 'Transactions' }] },
    { id: 'intention-lock', term: 'Intention lock', chapter: 18, def: 'A lock taken on a higher level of the granularity hierarchy (IS, IX or SIX) to announce that finer locks are held further down. It lets a request for a whole-table lock be checked without inspecting every row lock.', related: ['multiple-granularity', 'lock-compatibility'], see: [{ view: 'txn', label: 'Transactions' }] },
    { id: 'timestamp-ordering', term: 'Timestamp ordering', chapter: 18, def: 'A concurrency control protocol that gives each transaction a timestamp when it begins and only lets conflicting operations happen in timestamp order. A transaction whose operation would arrive out of order is rolled back.', related: ['thomas-write-rule', 'mvto'], see: [{ view: 'txn', label: 'Transactions' }] },
    { id: 'thomas-write-rule', term: 'Thomas\' write rule', chapter: 18, def: 'A relaxation of timestamp ordering: a write that has already been superseded by a write from a younger transaction is simply skipped instead of causing a rollback. It admits some schedules that are view serializable but not conflict serializable.', related: ['timestamp-ordering', 'view-serializability'], see: [{ view: 'txn', label: 'Transactions' }] },
    { id: 'validation', term: 'Validation (optimistic concurrency control)', chapter: 18, def: 'An optimistic protocol: transactions run without locks and keep their writes private, and at commit each is checked against the transactions that overlapped it in time; if there could be a conflict it is rolled back. It works well when conflicts are rare.', related: ['timestamp-ordering'], see: [{ view: 'txn', label: 'Transactions' }] },
    { id: 'mvcc', term: 'Multiversion concurrency control', chapter: 18, def: 'Concurrency control that keeps several versions of each data item, so a reader can use an older committed version instead of waiting for a writer. In Kwery and PostgreSQL each row version records the transaction that created it and the one that deleted it.', related: ['snapshot-isolation', 'mvto', 'mv2pl'], see: [{ view: 'storage', label: 'Storage' }, { view: 'txn', label: 'Transactions' }], example: 'select xmin, xmax, ctid, venue_code from venue limit 5;' },
    { id: 'mvto', term: 'Multiversion timestamp ordering', chapter: 18, def: 'Multiversion timestamp ordering: a read returns the newest version written by a transaction no younger than the reader, and a write is refused if a younger transaction has already read the version it would replace.', related: ['mvcc', 'timestamp-ordering'], see: [{ view: 'txn', label: 'Transactions' }] },
    { id: 'mv2pl', term: 'Multiversion two-phase locking', chapter: 18, def: 'Multiversion two-phase locking: transactions that update data follow rigorous two-phase locking, while read-only transactions read a consistent set of committed versions without taking locks.', related: ['mvcc', 'rigorous-2pl'], see: [{ view: 'txn', label: 'Transactions' }] },
    { id: 'predicate-lock', term: 'Predicate lock', chapter: 18, def: 'A lock on every row that satisfies a condition, including rows that do not exist yet but might be inserted. It prevents phantoms, but checking whether two conditions overlap is expensive in general.', related: ['phantom', 'next-key-locking'] },
    { id: 'next-key-locking', term: 'Next-key locking', chapter: 18, def: 'A practical replacement for predicate locks: when a range is scanned through an index, the key just past the end of the range is locked as well, so an insert into the range has to wait.', related: ['phantom', 'predicate-lock'], see: [{ view: 'txn', label: 'Transactions' }] },
    { id: 'ssi', term: 'Serializable snapshot isolation', chapter: 18, def: 'Serializable snapshot isolation: snapshot isolation plus tracking of read and write dependencies between concurrent transactions, rolling one back when they could form a cycle that no serial order explains. PostgreSQL\'s serializable level works this way.', related: ['snapshot-isolation', 'write-skew'], see: [{ view: 'txn', label: 'Transactions' }] },

    // ---- 19: recovery ----
    { id: 'log', term: 'Log', chapter: 19, def: 'An append-only record, kept on stable storage, of everything that changes the database: which transaction changed which item, its value before and after, and when transactions began, committed or aborted.', related: ['log-record', 'write-ahead-logging', 'lsn'], see: [{ view: 'log', label: 'Log' }] },
    { id: 'log-record', term: 'Log record', chapter: 19, def: 'One entry in the log. An update record names the transaction and the item and carries what is needed to redo and to undo the change; other kinds mark a transaction\'s start, commit or abort, or a checkpoint.', related: ['log', 'lsn'], see: [{ view: 'log', label: 'Log' }] },
    { id: 'stable-storage', term: 'Stable storage', chapter: 19, def: 'Storage assumed never to lose what is written to it, approximated in practice by writing copies to several independent devices, possibly at several sites. A commit is reported only after its log records are there.', related: ['durability', 'log'] },
    { id: 'write-ahead-logging', term: 'Write-ahead logging (WAL)', chapter: 19, def: 'The rule that the log records describing a change must reach stable storage before the changed page itself is written to disk, and that a transaction\'s commit record must be on stable storage before the commit is reported.', related: ['log', 'page-lsn', 'steal'], see: [{ view: 'log', label: 'Log' }, { view: 'buffer', label: 'Buffer pool' }] },
    { id: 'lsn', term: 'Log sequence number (LSN)', chapter: 19, def: 'A number that identifies a log record; numbers increase with the record\'s position in the log, so they also order the records.', related: ['page-lsn', 'log-record'], see: [{ view: 'log', label: 'Log' }] },
    { id: 'page-lsn', term: 'PageLSN', chapter: 19, def: 'A number stored in each page: the LSN of the latest logged change that the page contains. During redo, a log record is applied to a page only if its LSN is greater than the page\'s PageLSN.', related: ['lsn', 'aries'], see: [{ view: 'storage', label: 'Storage' }, { view: 'recovery', label: 'Crash and recovery' }] },
    { id: 'redo', term: 'Redo', chapter: 19, def: 'Applying a logged change to the data again to ensure it is really there. Redo must be safe to repeat: applying it twice has the same result as applying it once.', related: ['undo', 'repeating-history'], see: [{ view: 'recovery', label: 'Crash and recovery' }] },
    { id: 'undo', term: 'Undo', chapter: 19, def: 'Putting back the earlier value of an item that was changed by a transaction which did not commit. Under ARIES each undo step is itself written to the log.', related: ['redo', 'compensation-log-record'], see: [{ view: 'recovery', label: 'Crash and recovery' }] },
    { id: 'checkpoint', term: 'Checkpoint', chapter: 19, def: 'A point at which the system writes out dirty pages, or at least notes which pages are dirty, and adds a checkpoint record to the log, so recovery after a crash can begin near there rather than at the start of the log.', related: ['fuzzy-checkpoint', 'log'], see: [{ view: 'recovery', label: 'Crash and recovery' }] },
    { id: 'fuzzy-checkpoint', term: 'Fuzzy checkpoint', chapter: 19, def: 'A checkpoint that does not stop transactions or wait for every page to be written: it logs the list of dirty pages and active transactions and lets work continue.', related: ['checkpoint', 'dirty-page-table'] },
    { id: 'steal', term: 'Steal and no-steal', chapter: 19, def: 'Two buffer policies. With steal, a page that holds uncommitted changes may be written to disk to free its frame, so recovery has to be able to undo. With no-steal, such pages stay in memory until commit, which needs more buffer space.', related: ['force', 'write-ahead-logging'], see: [{ view: 'buffer', label: 'Buffer pool' }] },
    { id: 'force', term: 'Force and no-force', chapter: 19, def: 'Two commit policies. With force, every page a transaction changed is written to disk before the commit completes, so committed work never needs redoing. With no-force, commits are faster and recovery relies on redo from the log.', related: ['steal'], see: [{ view: 'buffer', label: 'Buffer pool' }] },
    { id: 'compensation-log-record', term: 'Compensation log record (CLR)', chapter: 19, def: 'A log record written while undoing a change, describing the undo; it is only ever redone, never undone. Its UndoNextLSN points to the next record still to be undone, so a crash in the middle of recovery does not repeat undo work.', related: ['undo', 'aries'], see: [{ view: 'recovery', label: 'Crash and recovery' }] },
    { id: 'aries', term: 'ARIES', chapter: 19, def: 'A log-based recovery method that, after a crash, makes three passes over the log: analysis (work out which pages may be dirty and which transactions were unfinished), redo (bring every page up to its state at the crash) and undo (roll back the unfinished transactions, logging compensation records).', related: ['analysis-pass', 'repeating-history', 'compensation-log-record', 'page-lsn'], see: [{ view: 'recovery', label: 'Crash and recovery' }] },
    { id: 'analysis-pass', term: 'Analysis pass', chapter: 19, def: 'The first pass of ARIES recovery. Starting from the last checkpoint, it scans the log to rebuild the transaction table and the dirty page table and to determine where redo must start.', related: ['aries', 'dirty-page-table', 'transaction-table'], see: [{ view: 'recovery', label: 'Crash and recovery' }] },
    { id: 'dirty-page-table', term: 'Dirty page table', chapter: 19, def: 'In ARIES, the list of pages whose latest changes might not yet be on disk, each with its RecLSN.', related: ['rec-lsn', 'analysis-pass'], see: [{ view: 'recovery', label: 'Crash and recovery' }] },
    { id: 'rec-lsn', term: 'RecLSN', chapter: 19, def: 'For each entry in the dirty page table, the LSN of the earliest change to that page that may be missing from disk. Redo starts at the smallest RecLSN in the table.', related: ['dirty-page-table', 'page-lsn'], see: [{ view: 'recovery', label: 'Crash and recovery' }] },
    { id: 'transaction-table', term: 'Transaction table', chapter: 19, def: 'In ARIES, the transactions that were still active at the time of the crash, each with the LSN of its most recent log record. Those that never committed are rolled back in the undo pass.', related: ['analysis-pass'], see: [{ view: 'recovery', label: 'Crash and recovery' }] },
    { id: 'repeating-history', term: 'Repeating history', chapter: 19, def: 'The ARIES approach to redo: every logged change is reapplied, whether its transaction committed or not, so the database returns to exactly its state at the crash before the unfinished transactions are undone.', related: ['aries', 'redo'], see: [{ view: 'recovery', label: 'Crash and recovery' }] },
    { id: 'shadow-paging', term: 'Shadow paging', chapter: 19, def: 'A recovery technique that uses no log: a transaction writes changed pages to new locations, and commit consists of switching one pointer from the old page table to the new one.', related: ['log'], see: [{ view: 'recovery', label: 'Crash and recovery' }] },
    { id: 'torn-page', term: 'Torn page', chapter: 19, def: 'A page that a crash interrupted while it was being written, leaving part of it old and part of it new. A checksum detects it, and a full image of the page in the log can restore it.', related: ['full-page-write'], see: [{ view: 'recovery', label: 'Crash and recovery' }] },
    { id: 'full-page-write', term: 'Full-page write', chapter: 19, def: 'Writing a complete copy of a page into the log the first time it is changed after a checkpoint, so that recovery can rebuild the page even if a later write to it was torn.', related: ['torn-page', 'write-ahead-logging'], see: [{ view: 'log', label: 'Log' }] },
    { id: 'remote-backup', term: 'Remote backup', chapter: 19, def: 'A copy of the database at a separate site that is kept up to date by sending it the log, ready to take over if the main site fails.', related: ['replication'] },

    // ---- 20-23: parallel and distributed ----
    { id: 'shared-memory', term: 'Shared memory', chapter: 20, def: 'A parallel machine design in which all processors use one common memory and the same disks. Processors can communicate quickly, but the design only scales to a modest number of processors.', related: ['shared-disk', 'shared-nothing'], see: [{ view: 'arch', label: 'Architectures' }] },
    { id: 'shared-disk', term: 'Shared disk', chapter: 20, def: 'A parallel machine design in which each node has its own processors and memory, but every node can reach all of the disks over a fast network.', related: ['shared-memory', 'shared-nothing'], see: [{ view: 'arch', label: 'Architectures' }] },
    { id: 'shared-nothing', term: 'Shared nothing', chapter: 20, def: 'A parallel machine design made of independent nodes, each with its own processors, memory and disks, that cooperate only by sending messages over a network. It can grow to thousands of nodes.', related: ['shared-disk', 'partitioning'], see: [{ view: 'arch', label: 'Architectures' }, { view: 'cluster', label: 'Cluster' }] },
    { id: 'speedup', term: 'Speedup and scaleup', chapter: 20, def: 'Two ways to measure a parallel system. Speedup: a task of fixed size finishes faster as hardware is added. Scaleup: a task that grows in step with the hardware still finishes in the same time.', related: ['shared-nothing'] },
    { id: 'partitioning', term: 'Partitioning', chapter: 21, def: 'Spreading the rows of a relation over several nodes or disks, for example in turn (round-robin), by a hash of an attribute, or by ranges of an attribute\'s values.', related: ['skew', 'replication'], see: [{ view: 'cluster', label: 'Cluster' }] },
    { id: 'skew', term: 'Skew', chapter: 21, def: 'Uneven sharing of work among nodes: some partitions receive many more rows (data skew) or much more processing (execution skew) than others, and the busiest node determines how long the whole job takes.', related: ['partitioning'], see: [{ view: 'cluster', label: 'Cluster' }] },
    { id: 'replication', term: 'Replication', chapter: 21, def: 'Storing copies of the same data on several nodes, so the data stays available when a node fails and reads can be spread out. Every update must reach every copy, either before the update is acknowledged or later.', related: ['partitioning', 'eventual-consistency', 'consensus'], see: [{ view: 'cluster', label: 'Cluster' }] },
    { id: 'two-phase-commit', term: 'Two-phase commit (2PC)', chapter: 23, def: 'A protocol for committing a transaction that changed data at several sites: a coordinator first asks every site to prepare and vote, then tells all of them to commit if every vote was yes, or to abort otherwise.', related: ['coordinator', 'blocking-problem', 'three-phase-commit'], see: [{ view: 'cluster', label: 'Cluster' }] },
    { id: 'coordinator', term: 'Coordinator', chapter: 23, def: 'In a distributed transaction, the site that drives the commit protocol: it collects the votes of the other sites, makes the decision and records it.', related: ['two-phase-commit'], see: [{ view: 'cluster', label: 'Cluster' }] },
    { id: 'blocking-problem', term: 'Blocking problem', chapter: 23, def: 'A weakness of two-phase commit: a site that has voted yes may not decide on its own, so if the coordinator fails at that point the site has to wait, still holding its locks, until the coordinator comes back.', related: ['two-phase-commit', 'three-phase-commit'] },
    { id: 'three-phase-commit', term: 'Three-phase commit', chapter: 23, def: 'A variant of two-phase commit that adds an extra round before the final decision so that sites can avoid blocking under certain kinds of failure. It costs more messages and makes assumptions about the network.', related: ['two-phase-commit', 'blocking-problem'] },
    { id: 'consensus', term: 'Consensus', chapter: 23, def: 'Getting a set of nodes to agree on a single value, or on a single ordered log of entries, even though some of them may fail, as long as a majority keeps working. Paxos and Raft are well-known solutions.', related: ['raft', 'leader-election'], see: [{ view: 'cluster', label: 'Cluster' }] },
    { id: 'raft', term: 'Raft', chapter: 23, def: 'A consensus protocol in which an elected leader adds entries to its log and copies them to the other nodes. An entry counts as committed once a majority of nodes have stored it.', related: ['consensus', 'leader-election'], see: [{ view: 'cluster', label: 'Cluster' }] },
    { id: 'leader-election', term: 'Leader election', chapter: 23, def: 'Choosing one node of a group to act as coordinator. In Raft, a node that stops receiving heartbeats from the leader puts itself forward as a candidate and becomes leader if a majority votes for it.', related: ['raft'], see: [{ view: 'cluster', label: 'Cluster' }] },
    { id: 'cap-theorem', term: 'CAP theorem', chapter: 23, def: 'The observation that when a network partition cuts a distributed system in two, it cannot be both consistent (every read returns the latest write) and available (every request gets a response); it has to give up one of them for the duration.', related: ['eventual-consistency', 'replication'] },
    { id: 'eventual-consistency', term: 'Eventual consistency', chapter: 23, def: 'A weak guarantee for replicated data: if no new updates are made, all replicas will sooner or later hold the same value. Until then a read may return an out-of-date value.', related: ['cap-theorem', 'replication'] },
    { id: 'distributed-query', term: 'Distributed query processing', chapter: 22, def: 'Answering a query whose data lives at several sites, which includes deciding where each operation runs so that as little data as possible has to travel over the network, for example by using a semijoin.', related: ['semijoin', 'partitioning'], see: [{ view: 'dquery', label: 'Distributed query' }] },
    { id: 'semijoin', term: 'Semijoin (⋉)', chapter: 22, def: 'The rows of r that have at least one matching row in s, with only r\'s columns kept. In a distributed join, sending just the join column of one side and getting back the semijoin reduces how much data crosses the network.', related: ['distributed-query'], see: [{ view: 'dquery', label: 'Distributed query' }] },
  );
})(typeof window !== 'undefined' ? window : globalThis);
